  pane.innerHTML=`<div class="mm-timeline-canvas" style="width:${axis+plot}px;--mm-axis:${axis}px;--mm-plot:${plot}px;--mm-visible-plot:${Math.max(40,pane.clientWidth-axis-20)}px;--mm-head-height:${level==='month'?33:66}px;--mm-grid:${(level==='month'?30:level==='week'?7:1)*ppd}px;${monthGrid}">${html}</div>`;
